(NULL, 'mc', 'Which is the tallest land animal?', 'fun_facts', '5_6', 'medium', true, '[{"label":"Elephant","isCorrect":false},{"label":"Horse","isCorrect":false},{"label":"Giraffe","isCorrect":true},{"label":"Camel","isCorrect":false}]'::jsonb, NULL, NULL, 'Giraffes are the tallest land animals on Earth, reaching heights of up to 6 metres!'),
(NULL, 'mc', 'What do plants need from the sun to grow?', 'fun_facts', '5_6', 'medium', true, '[{"label":"Warmth only","isCorrect":false},{"label":"Light for photosynthesis","isCorrect":true},{"label":"Darkness","isCorrect":false},{"label":"Rain from clouds","isCorrect":false}]'::jsonb, NULL, NULL, 'Plants use sunlight to make their own food through photosynthesis — turning light, water, and carbon dioxide into sugar.'),

-- age_band: 5_6 | difficulty: hard
(NULL, 'mc', 'Which country has the most wild kangaroos?', 'fun_facts', '5_6', 'hard', true, '[{"label":"New Zealand","isCorrect":false},{"label":"South Africa","isCorrect":false},{"label":"Australia","isCorrect":true},{"label":"Brazil","isCorrect":false}]'::jsonb, NULL, NULL, 'Kangaroos are native to Australia. There are actually more kangaroos in Australia than people!'),
(NULL, 'mc', 'What is the hardest natural material on Earth?', 'fun_facts', '5_6', 'hard', true, '[{"label":"Gold","isCorrect":false},{"label":"Iron","isCorrect":false},{"label":"Diamond","isCorrect":true},{"label":"Rock","isCorrect":false}]'::jsonb, NULL, NULL, 'Diamonds are the hardest natural material known — they are formed deep underground from carbon under extreme pressure.'),
(NULL, 'mc', 'How many bones does an adult human body have?', 'fun_facts', '5_6', 'hard', true, '[{"label":"106","isCorrect":false},{"label":"156","isCorrect":false},{"label":"206","isCorrect":true},{"label":"256","isCorrect":false}]'::jsonb, NULL, NULL, 'The adult human body has 206 bones. Babies are born with about 270 bones, but many fuse together as they grow.'),
(NULL, 'mc', 'What is the name of the largest ocean on Earth?', 'fun_facts', '5_6', 'hard', true, '[{"label":"Atlantic Ocean","isCorrect":false},{"label":"Indian Ocean","isCorrect":false},{"label":"Pacific Ocean","isCorrect":true},{"label":"Arctic Ocean","isCorrect":false}]'::jsonb, NULL, NULL, 'The Pacific Ocean is the largest and deepest ocean, covering more than 30% of Earth''s surface.'),
(NULL, 'mc', 'What makes the sky appear blue during the day?', 'fun_facts', '5_6', 'hard', true, '[{"label":"The ocean reflecting up","isCorrect":false},{"label":"Sunlight scattering off air molecules","isCorrect":true},{"label":"Blue paint in the clouds","isCorrect":false},{"label":"The sun is blue inside","isCorrect":false}]'::jsonb, NULL, NULL, 'Sunlight contains all colours. When it hits the atmosphere, air molecules scatter blue light more than other colours, making the sky appear blue.'),

-- age_band: 7_8 | difficulty: easy
(NULL, 'mc', 'What gas do humans breathe in to survive?', 'fun_facts', '7_8', 'easy', true, '[{"label":"Carbon dioxide","isCorrect":false},{"label":"Nitrogen","isCorrect":false},{"label":"Oxygen","isCorrect":true},{"label":"Hydrogen","isCorrect":false}]'::jsonb, NULL, NULL, 'Humans need oxygen to survive. We breathe in air, which is about 21% oxygen, and breathe out carbon dioxide.'),
